noteContentFormat:
{# SOURCE: https://github.com/churnish/web-clipper-templates #}{# Lines holding only tags print nothing. In regexes, \x22 is a double quote and \x5C a backslash. #}{% set reel = meta:property:og:url contains "/reel/" %}
{% set name = meta:property:og:title|replace:"/ on Instagram.*$/s":""|escape_md %}
{# Caption: the description meta between its quotes; no quote means no caption. #}{% set caption = meta:name:description|replace:"/^[^\x22]*$/":""|replace:"/^.*?\d\d\d\d. ./s":""|replace:"/.[.] *$/s":""|replace:"/[\u200B\u2060-\u2064\uFEFF]/g":""|replace:"/@([A-Za-z0-9_.]*[A-Za-z0-9_])/g":"[@$1](https://www.instagram.com/$1/)"|replace:"/#([0-9A-Za-z_À-ɏЀ-ӿ]+)/g":"[\\\\#$1](https://www.instagram.com/explore/tags/$1/)"|replace:"/ +$/gm":""|trim|replace:"/^./s":":** $&"|replace:"/^$/":"**" %}
{# The first script holding "candidates" is the post; later ones are other posts. #}{% set post = selector:script[type$=json]|join:"¶"|replace:"/^(.*?[^_]candidates[^¶]*).*$/s":"$1"|replace:"/^.*¶/s":"" %}
{# First "url" of each "candidates" list is full size; the last repeats the cover. #}{% set images = post|replace:"/[^_]candidates[^}]*?url[^a-z]+([^\x22]+)/g":"¶$1¶"|replace:"/\x5C/g":""|replace:"u0025":"%"|split:"¶"|nth:2n|unique %}
{# Reels keep only their cover. Carousels with a video slide get a label. #}{% if reel %}{% set images = images|first %}{% else %}{% set video = post|replace:"/^.*?carousel_media[^a-z0-9_,]*\[.*?(?:media_type\D+2\D|VideoMedia).*$/s":"¶"|replace:"/^[^¶].*$/s":"" %}{% endif %}
**{% if reel %}🩳 {% else %}📢 {% endif %}{{name}}{{caption}}

{% if video %}**Has video**

{% endif %}{{images|image|join:"\n"|replace:"/^!\[\]([^\n]*)$/":"![|392]$1"|replace:"/(.+\n.+)\n/g":"$1\n\n"}}
